package Test3;

public class String_methods {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		String a="Java Programming";
		System.out.println("Length of string is "+a.length());
		System.out.println("Character: "+a.charAt(1));
		System.out.println("Substring: "+a.substring(5));
		System.out.println("Upper case: "+a.toUpperCase());
		System.out.println("Lower case: "+a.toLowerCase());
		System.out.println("Replace: "+a.replace("a","b"));
	}

}
